window.ENEM_REPERTORIES=[{"id":"rep-1","title":"Merlí","text":"Na obra televisiva “Merlí”, criada e escrita por Héctor Lozano, evidencia-se a importância do diálogo filosófico para a construção do pensamento crítico e da autonomia dos estudantes.","usage":"Educação • formação crítica e métodos de ensino.","source":"R3, p. 1","category":"Obras, músicas e narrativas","axes":["Educação"],"kind":"Catálogo v3","warning":null},{"id":"rep-2","title":"Admirável Mundo Novo","text":"Na obra “Admirável Mundo Novo”, de Aldous Huxley, evidencia-se o controle social por meio do condicionamento dos indivíduos e da limitação de sua autonomia para questionar a ordem estabelecida.","usage":"Educação / Tecnologia / Cidadania • pensamento crítico, informação e controle.","source":"R3, p. 1","category":"Obras, músicas e narrativas","axes":["Educação","Tecnologia","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-3","title":"Segunda Chamada","text":"Na obra televisiva “Segunda Chamada”, escrita por Carla Faour e Julia Spadaccini, evidencia-se a luta de professores e estudantes da educação de jovens e adultos diante de obstáculos sociais, econômicos e institucionais à permanência escolar.","usage":"Educação / Cidadania • EJA, evasão e desigualdade de oportunidades.","source":"R3, p. 1","category":"Obras, músicas e narrativas","axes":["Educação","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-4","title":"Cálice","text":"Na obra musical “Cálice”, de Chico Buarque e Gilberto Gil, evidencia-se a denúncia do silenciamento e da repressão à liberdade de expressão durante a ditadura.","usage":"Cultura / Cidadania / Educação • censura e democratização do conhecimento.","source":"R3, p. 1","category":"Obras, músicas e narrativas","axes":["Educação","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-5","title":"Sex Education","text":"Na obra televisiva “Sex Education”, criada por Laurie Nunn, evidencia-se a dificuldade de adolescentes para lidar com sexualidade, afetos e dúvidas em ambientes marcados por tabus e comunicação insuficiente.","usage":"Educação / Saúde / Minorias • formação integral, acolhimento e informação.","source":"R3, p. 1","category":"Obras, músicas e narrativas","axes":["Educação","Saúde","Minorias"],"kind":"Catálogo v3","warning":null},{"id":"rep-6","title":"Criança Não Trabalha","text":"Na obra musical “Criança Não Trabalha”, de Arnaldo Antunes e Paulo Tatit, evidencia-se a valorização do brincar e de experiências próprias da infância, em oposição à exploração precoce pelo trabalho.","usage":"Minorias / Educação / Cidadania • proteção e desenvolvimento infantil.","source":"R6, p. 1","category":"Obras, músicas e narrativas","axes":["Educação","Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-7","title":"Up — Altas Aventuras","text":"Na obra cinematográfica “Up — Altas Aventuras”, dirigida por Pete Docter, com codireção de Bob Peterson, evidencia-se a reconstrução dos projetos de vida de Carl após perdas e mudanças, permitindo discutir autonomia e vínculos no envelhecimento.","usage":"Minorias / Saúde • velhice, participação e combate ao etarismo.","source":"R7, p. 2","category":"Obras, músicas e narrativas","axes":["Saúde","Minorias"],"kind":"Catálogo v3","warning":null},{"id":"rep-8","title":"Memórias Póstumas de Brás Cubas","text":"Na obra “Memórias Póstumas de Brás Cubas”, de Machado de Assis, evidencia-se a crítica às aparências, aos privilégios e à busca de prestígio de uma elite. Essa crítica pode fundamentar uma análise da valorização social baseada em status e utilidade.","usage":"Minorias / Cidadania • a conexão com a desvalorização dos idosos é argumentativa; a velhice não é o tema central do romance.","source":"R2, p. 2","category":"Obras, músicas e narrativas","axes":["Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-9","title":"Identidade","text":"Na obra musical “Identidade”, de Jorge Aragão, evidencia-se a defesa da memória e das raízes negras como parte da construção da identidade e da resistência ao apagamento histórico.","usage":"Cultura / Minorias • herança africana, memória e racismo.","source":"R4, p. 1","category":"Obras, músicas e narrativas","axes":["Minorias","Cultura"],"kind":"Catálogo v3","warning":null},{"id":"rep-10","title":"Diário de um Detento","text":"Na obra musical “Diário de um Detento”, interpretada pelos Racionais MC’s, evidencia-se a violência e a desumanização vividas no sistema prisional, dando visibilidade a sujeitos socialmente marginalizados.","usage":"Cidadania / Minorias / Cultura • exclusão, violência e reconhecimento.","source":"R4, p. 1","category":"Obras, músicas e narrativas","axes":["Minorias","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-11","title":"O Canto das Três Raças","text":"Na obra musical “O Canto das Três Raças”, interpretada por Clara Nunes, evidencia-se a memória de sofrimentos e lutas presentes na formação brasileira, permitindo problematizar o silenciamento de grupos e a valorização de suas contribuições culturais.","usage":"Cultura / Minorias • diversidade, resistência e memória coletiva.","source":"R4, p. 1","category":"Obras, músicas e narrativas","axes":["Minorias","Cultura"],"kind":"Catálogo v3","warning":null},{"id":"rep-12","title":"Rap da Felicidade","text":"Na obra musical “Rap da Felicidade”, de Cidinho e Doca, evidencia-se a reivindicação de paz, dignidade e reconhecimento por moradores de periferias estigmatizadas.","usage":"Cultura / Cidadania / Minorias • direito à cidade e combate ao preconceito territorial.","source":"R4, p. 1","category":"Obras, músicas e narrativas","axes":["Minorias","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-13","title":"Brasis","text":"Na obra musical “Brasis”, interpretada por Seu Jorge, evidencia-se o contraste entre experiências sociais diferentes no mesmo país, marcado por diversidade e profundas desigualdades.","usage":"Cultura / Cidadania • desigualdade e pluralidade da sociedade brasileira.","source":"R4, p. 1","category":"Obras, músicas e narrativas","axes":["Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-14","title":"O Show Tem Que Continuar","text":"Na obra musical “O Show Tem Que Continuar”, interpretada pelo Fundo de Quintal, evidencia-se a persistência diante de dificuldades. O anexo aproxima essa ideia da resistência de manifestações populares à desvalorização.","usage":"Cultura • continuidade, resistência e preservação de manifestações populares.","source":"R4, p. 1","category":"Obras, músicas e narrativas","axes":["Cultura"],"kind":"Catálogo v3","warning":null},{"id":"rep-15","title":"A República","text":"Na obra “A República”, de Platão, evidencia-se a investigação sobre a justiça e a organização de uma cidade justa, relacionando educação e vida coletiva.","usage":"Cidadania / Educação • R2 alerta contra a simples menção a uma sociedade ideal sem ligação concreta com o tema.","source":"R2, p. 1","category":"Obras, músicas e narrativas","axes":["Educação","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-16","title":"Constituição de 1988","text":"Na obra normativa “Constituição da República Federativa do Brasil”, elaborada pela Assembleia Nacional Constituinte, evidencia-se a proteção da dignidade e dos direitos fundamentais. No art. 196, a saúde é reconhecida como direito de todos e dever do Estado.","usage":"Saúde / Cidadania / Minorias • contraste entre garantia jurídica e acesso efetivo; não se trata de obra de ficção.","source":"R2, p. 2; R5, p. 1; R7, p. 1","category":"Leis e direitos","axes":["Saúde","Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-17","title":"Jerome Bruner","text":"Conforme Jerome Bruner, a aprendizagem envolve a construção ativa do conhecimento, e não somente a recepção ou a memorização de informações.","usage":"Educação / Cultura • autonomia e participação do estudante.","source":"R1, p. 4; R4, p. 3","category":"Pensadores e conceitos","axes":["Educação","Cultura"],"kind":"Catálogo v3","warning":null},{"id":"rep-18","title":"David Ausubel","text":"Conforme David Ausubel, a aprendizagem significativa relaciona conhecimentos novos ao que o estudante já sabe, tornando relevante o diálogo com suas experiências.","usage":"Educação / Cultura • aprendizagem e realidade do aluno.","source":"R1, p. 4; R4, p. 3","category":"Pensadores e conceitos","axes":["Educação","Cultura"],"kind":"Catálogo v3","warning":null},{"id":"rep-19","title":"Lev Vygotsky","text":"Conforme Lev Vygotsky, o desenvolvimento humano é mediado pelas interações sociais e pelo contexto cultural em que o sujeito aprende.","usage":"Educação / Cultura • mediação e ambientes de aprendizagem.","source":"R1, p. 4; R4, p. 3","category":"Pensadores e conceitos","axes":["Educação","Cultura"],"kind":"Catálogo v3","warning":null},{"id":"rep-20","title":"Paulo Freire","text":"Conforme Paulo Freire, uma educação problematizadora e dialógica favorece a consciência crítica e a participação na transformação social, em oposição à passividade do educando.","usage":"Educação / Cidadania • formação crítica e emancipação.","source":"R1, p. 4","category":"Pensadores e conceitos","axes":["Educação","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-21","title":"César Coll","text":"Conforme César Coll, a formação escolar precisa desenvolver competências para analisar, selecionar e utilizar informações, em vez de apenas acumulá-las.","usage":"Educação / Tecnologia • leitura crítica e letramento informacional.","source":"R3, p. 2","category":"Pensadores e conceitos","axes":["Educação","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-22","title":"Carl Sagan","text":"Conforme Carl Sagan, o pensamento científico envolve questionamento racional e exame de evidências para compreender a realidade.","usage":"Educação / Saúde / Tecnologia • ciência, fontes e desinformação.","source":"R3, p. 2","category":"Pensadores e conceitos","axes":["Educação","Saúde","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-23","title":"Jürgen Habermas","text":"Conforme Jürgen Habermas, o debate público e a comunicação são centrais à formação da opinião e à participação na vida coletiva.","usage":"Cidadania / Tecnologia • qualidade do debate e visibilidade das demandas sociais.","source":"R6, p. 1","category":"Pensadores e conceitos","axes":["Tecnologia","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-24","title":"Veena Das","text":"Conforme Veena Das, a violência pode se incorporar às relações cotidianas, tornando-se menos visível quando é naturalizada.","usage":"Minorias / Saúde / Cidadania • violências cotidianas e silenciamento.","source":"R6, p. 2","category":"Pensadores e conceitos","axes":["Saúde","Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-25","title":"Didier Fassin","text":"Conforme Didier Fassin, a consideração desigual do valor das vidas ajuda a compreender por que sofrimentos e privações de certos grupos recebem menor atenção social.","usage":"Minorias / Saúde / Cidadania • prioridades, cuidado e desigualdade de proteção.","source":"R6, p. 2","category":"Pensadores e conceitos","axes":["Saúde","Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-26","title":"Nancy Fraser","text":"Conforme Nancy Fraser, o reconhecimento desigual de grupos reforça a marginalização e dificulta sua participação em condições de igualdade.","usage":"Minorias / Cultura / Cidadania • reconhecimento e exclusão.","source":"R6, p. 2","category":"Pensadores e conceitos","axes":["Minorias","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-27","title":"Marshall McLuhan","text":"Conforme Marshall McLuhan, o próprio meio de comunicação participa da organização da experiência e da percepção, não sendo um canal inteiramente neutro.","usage":"Tecnologia / Cultura • efeitos dos formatos e dos meios de comunicação.","source":"R6, p. 1","category":"Pensadores e conceitos","axes":["Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-28","title":"Neil Postman","text":"Conforme Neil Postman, a transformação da informação em entretenimento pode simplificar questões complexas e enfraquecer a análise crítica do debate público.","usage":"Tecnologia / Educação / Cultura • superficialidade e consumo de informação.","source":"R1, p. 4; R4, p. 3; R6, p. 1","category":"Pensadores e conceitos","axes":["Educação","Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-29","title":"Guy Debord","text":"Conforme Guy Debord, na sociedade do espetáculo, as relações sociais são mediadas por imagens, e a aparência e o consumo ganham centralidade.","usage":"Tecnologia / Cultura / Cidadania • espetáculo, imagem e visibilidade.","source":"R1, p. 4; R6, p. 2","category":"Pensadores e conceitos","axes":["Cultura","Tecnologia","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-30","title":"Jean Baudrillard","text":"Conforme Jean Baudrillard, as representações e os simulacros podem se sobrepor à experiência do real, produzindo uma hiper-realidade.","usage":"Tecnologia / Cultura • representações midiáticas e percepção da realidade.","source":"R6, p. 2","category":"Pensadores e conceitos","axes":["Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-31","title":"Elisabeth Noelle-Neumann","text":"Conforme Elisabeth Noelle-Neumann, o receio de isolamento pode levar pessoas a silenciar opiniões percebidas como minoritárias, reforçando a impressão de consenso.","usage":"Tecnologia / Minorias / Cidadania • espiral do silêncio.","source":"R6, p. 2","category":"Pensadores e conceitos","axes":["Minorias","Tecnologia","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-32","title":"Sherry Turkle","text":"Conforme Sherry Turkle, as tecnologias de comunicação transformam as relações e podem limitar a atenção à conversa presencial e à experiência do outro.","usage":"Tecnologia / Saúde • vínculos, atenção e empatia.","source":"R6, p. 2","category":"Pensadores e conceitos","axes":["Saúde","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-33","title":"Manuel Castells","text":"Conforme Manuel Castells, a sociedade em rede reorganiza a produção e a circulação de informações, conhecimentos e relações de poder.","usage":"Tecnologia / Educação / Cidadania • redes e desigualdades de participação.","source":"R3, p. 2","category":"Pensadores e conceitos","axes":["Educação","Tecnologia","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-34","title":"Byung-Chul Han","text":"Conforme Byung-Chul Han, a pressão por desempenho e o excesso de estímulos e informações podem reduzir o espaço de reflexão e aprofundamento.","usage":"Tecnologia / Saúde / Educação • produtividade, atenção e formação crítica.","source":"R1, p. 5; R3, p. 2","category":"Pensadores e conceitos","axes":["Educação","Saúde","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-35","title":"José van Dijck","text":"Conforme José van Dijck, as plataformas digitais organizam a circulação de conteúdos segundo mecanismos tecnológicos e interesses econômicos que influenciam sua visibilidade.","usage":"Tecnologia / Cultura • algoritmos e circulação cultural.","source":"R1, p. 4; R4, p. 3","category":"Pensadores e conceitos","axes":["Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-36","title":"Nick Couldry","text":"Conforme Nick Couldry, os meios de comunicação exercem poder simbólico ao favorecer a visibilidade de determinadas vozes e experiências sociais.","usage":"Tecnologia / Cultura / Minorias • representação e silenciamento.","source":"R1, p. 4; R4, p. 3","category":"Pensadores e conceitos","axes":["Minorias","Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-37","title":"Sonia Livingstone","text":"Conforme Sonia Livingstone, a educação midiática é importante para compreender, avaliar e participar criticamente dos ambientes de comunicação.","usage":"Educação / Tecnologia / Cultura • leitura crítica da mídia.","source":"R4, p. 3","category":"Pensadores e conceitos","axes":["Educação","Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-38","title":"Mark Deuze","text":"Conforme Mark Deuze, a vida contemporânea se desenvolve em estreita relação com as mídias e as tecnologias, que participam da experiência cultural.","usage":"Tecnologia / Cultura • mediação tecnológica da vida cotidiana.","source":"R4, p. 3","category":"Pensadores e conceitos","axes":["Cultura","Tecnologia"],"kind":"Catálogo v3","warning":null},{"id":"rep-39","title":"Edgar Morin","text":"Conforme Edgar Morin, a fragmentação do saber dificulta a compreensão de fenômenos complexos, que exigem relacionar diferentes dimensões e conhecimentos.","usage":"Educação / Meio Ambiente • conexão ambiental editorial: relações entre território, saúde, economia e direitos.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Educação","Meio Ambiente"],"kind":"Catálogo v3","warning":null},{"id":"rep-40","title":"Raquel Rolnik","text":"Conforme Raquel Rolnik, a segregação urbana restringe o acesso de grupos sociais a serviços, equipamentos e oportunidades de participação.","usage":"Cidadania / Cultura / Meio Ambiente • conexão ambiental editorial: infraestrutura e exposição desigual a riscos.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Cultura","Meio Ambiente","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-41","title":"Loïc Wacquant","text":"Conforme Loïc Wacquant, a marginalização territorial e institucional contribui para reproduzir a exclusão de populações periféricas.","usage":"Cidadania / Minorias / Cultura • estigma territorial e acesso a direitos.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Minorias","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-42","title":"Milton Santos","text":"Conforme Milton Santos, a organização desigual do espaço e os efeitos seletivos da globalização distribuem oportunidades de maneira assimétrica.","usage":"Cidadania / Cultura / Meio Ambiente • acesso ao território e aos serviços; vínculo ambiental editorial.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Cultura","Meio Ambiente","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-43","title":"Jessé Souza","text":"Conforme Jessé Souza, mecanismos sociais reproduzem estruturalmente a desigualdade brasileira e limitam o reconhecimento de grupos marginalizados.","usage":"Cidadania / Minorias / Cultura • reprodução da desigualdade e acesso a direitos.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Minorias","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-44","title":"Amartya Sen","text":"Conforme Amartya Sen, o desenvolvimento depende da ampliação das capacidades e das oportunidades reais de escolha das pessoas.","usage":"Cidadania / Saúde / Meio Ambiente • condições de vida; ligação com água e saneamento é editorial.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Saúde","Meio Ambiente","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-45","title":"Boaventura de Sousa Santos","text":"Conforme Boaventura de Sousa Santos, uma democracia inclusiva precisa enfrentar a invisibilização de grupos e permitir sua participação nas instituições.","usage":"Cidadania / Minorias • participação e inclusão democrática.","source":"R1, p. 5","category":"Pensadores e conceitos","axes":["Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-46","title":"Achille Mbembe","text":"Conforme Achille Mbembe, o exercício seletivo do poder expõe determinados grupos a condições mais intensas de vulnerabilidade e de ameaça à vida.","usage":"Cidadania / Minorias / Saúde • proteção desigual e estruturas de poder.","source":"R1, p. 5","category":"Pensadores e conceitos","axes":["Saúde","Minorias","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-47","title":"Peter Berger e Thomas Luckmann","text":"Conforme Peter Berger e Thomas Luckmann, a realidade social e os conhecimentos do cotidiano se constroem em processos coletivos, nos quais práticas podem ser aceitas como naturais.","usage":"Cidadania / Cultura / Minorias • construção social e naturalização.","source":"R1, p. 5; R4, p. 3","category":"Pensadores e conceitos","axes":["Minorias","Cultura","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-48","title":"Herbert Marcuse","text":"Conforme Herbert Marcuse, formas de dominação da sociedade moderna podem estimular o conformismo e limitar a capacidade de questionar padrões estabelecidos.","usage":"Cidadania / Cultura / Tecnologia • conformismo e crítica social.","source":"R1, p. 4; R4, p. 3","category":"Pensadores e conceitos","axes":["Cultura","Tecnologia","Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"rep-49","title":"Aristóteles","text":"Conforme Aristóteles, a vida humana tem dimensão política e se organiza em comunidade, o que permite refletir sobre participação e vida coletiva.","usage":"Cidadania • R2 usa a menção genérica ao “animal político” como exemplo pouco produtivo: a conexão com o tema precisa ser demonstrada.","source":"R2, p. 1","category":"Pensadores e conceitos","axes":["Cidadania"],"kind":"Catálogo v3","warning":null},{"id":"apoio-historia","title":"Conexões históricas dos anexos","text":"A colonização exploratória e a escravidão ajudam a contextualizar a concentração de privilégios e a exclusão. A política de branqueamento e a catequização indígena permitem discutir imposição de padrões e apagamento cultural. A Semana de Arte Moderna de 1922 problematiza a identidade nacional; a Era Vargas associa valorização do samba e do rádio a controle estatal. A Reforma Pereira Passos ilustra modernização urbana excludente; a Ditadura Militar, censura e restrição de participação. São processos históricos, não obras de um autor: por isso, não foram artificialmente convertidos em títulos. A repressão ao samba deve ser distinguida da criminalização legal da capoeira. [R1, pp. 3 e 5; R4, pp. 1–2]","usage":"Contextualizar o processo e explicar sua relação com o problema; a repressão ao samba deve ser distinguida da criminalização legal da capoeira.","source":"Redação v3 — quadro Conexões históricas dos anexos [R1, pp. 3 e 5; R4, pp. 1–2].","category":"Históricos","axes":["Cultura","Cidadania","Minorias"],"kind":"Apoio da v3","warning":null},{"id":"lei-0","title":"Constituição de 1988 — arts. 205 e 206, I–IV e VI–VII","text":"Art. 205. A educação, direito de todos e dever do Estado e da família, será promovida e incentivada com a colaboração da sociedade, visando ao pleno desenvolvimento da pessoa, seu preparo para o exercício da cidadania e sua qualificação para o trabalho. Art. 206. O ensino será ministrado com base nos seguintes princípios: I – igualdade de condições para o acesso e permanência na escola; II – liberdade de aprender, ensinar, pesquisar e divulgar o pensamento, a arte e o saber; III – pluralismo de ideias e de concepções pedagógicas, e coexistência de instituições públicas e privadas de ensino; IV – gratuidade do ensino público em estabelecimentos oficiais; [...] VI – gestão democrática do ensino público, na forma da lei; VII – garantia de padrão de qualidade;","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Educação.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Educação"],"kind":"Motivador jurídico da v3","warning":null},{"id":"lei-1","title":"Constituição de 1988 — arts. 196 e 197","text":"Art. 196. A saúde é direito de todos e dever do Estado, garantido mediante políticas sociais e econômicas que visem à redução do risco de doença e de outros agravos e ao acesso universal e igualitário às ações e serviços para sua promoção, proteção e recuperação. Art. 197. São de relevância pública as ações e serviços de saúde, cabendo ao Poder Público dispor, nos termos da lei, sobre sua regulamentação, fiscalização e controle, devendo sua execução ser feita diretamente ou através de terceiros e, também, por pessoa física ou jurídica de direito privado.","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Saúde.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Saúde"],"kind":"Motivador jurídico da v3","warning":null},{"id":"lei-2","title":"Constituição de 1988 — art. 5º, caput e I, III e XLI","text":"Art. 5º Todos são iguais perante a lei, sem distinção de qualquer natureza, garantindo-se aos brasileiros e aos estrangeiros residentes no País a inviolabilidade do direito à vida, à liberdade, à igualdade, à segurança e à propriedade, nos termos seguintes: I – homens e mulheres são iguais em direitos e obrigações, nos termos desta Constituição; [...] III – ninguém será submetido a tortura nem a tratamento desumano ou degradante; [...] XLI – a lei punirá qualquer discriminação atentatória dos direitos e liberdades fundamentais;","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Minorias.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Minorias"],"kind":"Motivador jurídico da v3","warning":null},{"id":"lei-3","title":"Constituição de 1988 — arts. 215, caput e §§ 1º–2º, e 216, caput e I–III","text":"Art. 215. O Estado garantirá a todos o pleno exercício dos direitos culturais e acesso às fontes da cultura nacional, e apoiará e incentivará a valorização e a difusão das manifestações culturais. § 1º O Estado protegerá as manifestações das culturas populares, indígenas e afro-brasileiras, e das de outros grupos participantes do processo civilizatório nacional. § 2º A lei disporá sobre a fixação de datas comemorativas de alta significação para os diferentes segmentos étnicos nacionais. [...] Art. 216. Constituem patrimônio cultural brasileiro os bens de natureza material e imaterial, tomados individualmente ou em conjunto, portadores de referência à identidade, à ação, à memória dos diferentes grupos formadores da sociedade brasileira, nos quais se incluem: I – as formas de expressão; II – os modos de criar, fazer e viver; III – as criações científicas, artísticas e tecnológicas;","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Cultura.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Cultura"],"kind":"Motivador jurídico da v3","warning":null},{"id":"lei-4","title":"Constituição de 1988 — art. 218, caput e §§ 1º–3º","text":"Art. 218. O Estado promoverá e incentivará o desenvolvimento científico, a pesquisa, a capacitação científica e tecnológica e a inovação. § 1º A pesquisa científica básica e tecnológica receberá tratamento prioritário do Estado, tendo em vista o bem público e o progresso da ciência, tecnologia e inovação. § 2º A pesquisa tecnológica voltar-se-á preponderantemente para a solução dos problemas brasileiros e para o desenvolvimento do sistema produtivo nacional e regional. § 3º O Estado apoiará a formação de recursos humanos nas áreas de ciência, pesquisa, tecnologia e inovação, inclusive por meio do apoio às atividades de extensão tecnológica, e concederá aos que delas se ocupem meios e condições especiais de trabalho.","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Tecnologia.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Tecnologia"],"kind":"Motivador jurídico da v3","warning":null},{"id":"lei-5","title":"Constituição de 1988 — art. 225, caput e § 1º, I e VI–VII","text":"Art. 225. Todos têm direito ao meio ambiente ecologicamente equilibrado, bem de uso comum do povo e essencial à sadia qualidade de vida, impondo-se ao Poder Público e à coletividade o dever de defendê-lo e preservá-lo para as presentes e futuras gerações. § 1º Para assegurar a efetividade desse direito, incumbe ao Poder Público: I – preservar e restaurar os processos ecológicos essenciais e prover o manejo ecológico das espécies e ecossistemas; [...] VI – promover a educação ambiental em todos os níveis de ensino e a conscientização pública para a preservação do meio ambiente; VII – proteger a fauna e a flora, vedadas, na forma da lei, as práticas que coloquem em risco sua função ecológica, provoquem a extinção de espécies ou submetam os animais a crueldade;","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Meio Ambiente.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Meio Ambiente"],"kind":"Motivador jurídico da v3","warning":null},{"id":"lei-6","title":"Constituição de 1988 — arts. 5º, XXXV, 6º e 37, caput","text":"Art. 5º [...] XXXV – a lei não excluirá da apreciação do Poder Judiciário lesão ou ameaça a direito; [...] Art. 6º São direitos sociais a educação, a saúde, a alimentação, o trabalho, a moradia, o transporte, o lazer, a segurança, a previdência social, a proteção à maternidade e à infância, a assistência aos desamparados, na forma desta Constituição. [...] Art. 37. A administração pública direta e indireta de qualquer dos Poderes da União, dos Estados, do Distrito Federal e dos Municípios obedecerá aos princípios de legalidade, impessoalidade, moralidade, publicidade e eficiência e, também, ao seguinte:","usage":"Contraste entre garantia jurídica e acesso efetivo. Eixo de aplicação na apostila: Cidadania.","source":"Redação v3 — TEXTO II dos temas de treino; Constituição Federal, edição do Senado compilada até a EC nº 138/2025.","category":"Leis e direitos","axes":["Cidadania"],"kind":"Motivador jurídico da v3","warning":null},{"id":"modelo-darcy","title":"Darcy Ribeiro — referência do modelo base","text":"Em primeira análise, a deficiência governamental intensifica os obstáculos que limitam [referência temática do tema]. Sob essa perspectiva, Darcy Ribeiro sustenta que o Estado deve assegurar educação, cidadania e igualdade de oportunidades, pois a omissão do poder público pode agravar o desenvolvimento social. Tal reflexão aplica-se ao Brasil, no qual, embora o país reconheça a importância da -------, princípio destacado por Ribeiro, as medidas adotadas ainda não alcançam plenamente a sociedade, haja vista [causa 1 com exemplo]. Soma-se a isso [causa 2 com exemplo]. Logo, destaca-se o descompasso entre o potencial e a realidade brasileira.","usage":"Use apenas depois de confirmar a obra e a pertinência. O texto acima conserva os campos em aberto do modelo, não é uma citação literal do autor.","source":"Redação v3 — Modelo base, página 3.","category":"Pensadores e conceitos","axes":["Educação","Cidadania"],"kind":"Modelo base: atribuição não verificada","warning":"Estrutura do modelo base, com revisão linguística. As formulações atribuídas a Darcy Ribeiro e Muniz Sodré foram mantidas como paráfrases do modelo fornecido, não como citações literais verificadas. Confirme a obra e a pertinência antes do uso. Os agentes e as causas devem ser ajustados ao tema; os mesmos ministérios não servem para toda proposta.\n"},{"id":"modelo-muniz","title":"Muniz Sodré — referência do modelo base","text":"Ademais, a lacuna midiática contribui para a reprodução de situações que comprometem a efetivação de [referência temática]. Segundo Muniz Sodré, os meios de comunicação participam da construção das percepções coletivas e, quando orientados por interesses específicos, podem moldar comportamentos. Isso ocorre porque, no Brasil, determinadas questões permanecem à margem da atenção popular, teoria concebida por Muniz, visto que os veículos midiáticos pouco ampliam sua discussão, tendo em vista [causa 1 com exemplo]. Outrossim, [causa 2 com exemplo]. Por conseguinte, enquanto a desinformação prevalecer, o Brasil permanecerá com essa mazela histórica.","usage":"Use apenas depois de confirmar a obra e a pertinência. O texto acima conserva os campos em aberto do modelo, não é uma citação literal do autor.","source":"Redação v3 — Modelo base, página 3.","category":"Pensadores e conceitos","axes":["Tecnologia","Cidadania"],"kind":"Modelo base: atribuição não verificada","warning":"Estrutura do modelo base, com revisão linguística. As formulações atribuídas a Darcy Ribeiro e Muniz Sodré foram mantidas como paráfrases do modelo fornecido, não como citações literais verificadas. Confirme a obra e a pertinência antes do uso. Os agentes e as causas devem ser ajustados ao tema; os mesmos ministérios não servem para toda proposta.\n"},{"id":"doc-001","title":"Dignidade e igualdade de origem","text":"A Declaração Universal dos Direitos Humanos afirma que todas as pessoas nascem livres e iguais em dignidade e direitos.","usage":"Contraste a igualdade de dignidade com práticas que desumanizam um grupo; explique o mecanismo da exclusão.","source":"Art. 1 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-002","title":"Direitos sem discriminação","text":"Os direitos declarados não dependem de raça, sexo, língua, religião, origem ou outra condição.","usage":"Mostre por que critérios discriminatórios de acesso a serviços contrariam uma referência universal de direitos.","source":"Art. 2 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-003","title":"Vida, liberdade e segurança pessoal","text":"Vida, liberdade e segurança pessoal são reconhecidas como direitos de toda pessoa.","usage":"Relacione a violência cotidiana à restrição de circulação e autonomia, sem defender soluções que violem outros direitos.","source":"Art. 3 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Violência","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-004","title":"Proibição da escravidão","text":"Escravidão, servidão e tráfico de escravos são proibidos pela declaração.","usage":"Introduza o combate ao trabalho em condições análogas à escravidão e depois especifique a legislação brasileira pertinente.","source":"Art. 4 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Trabalho","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-005","title":"Proteção contra tortura","text":"A declaração proíbe tortura e tratamento ou punição cruéis, desumanos ou degradantes.","usage":"Argumente que políticas de segurança e instituições de custódia devem proteger a integridade humana.","source":"Art. 5 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Violência","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-006","title":"Reconhecimento como pessoa perante a lei","text":"Toda pessoa tem direito ao reconhecimento de sua personalidade jurídica.","usage":"Discuta invisibilidade documental e o acesso à cidadania, distinguindo dignidade humana de possuir um documento.","source":"Art. 6 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-007","title":"Igual proteção da lei","text":"A igualdade perante a lei inclui proteção contra discriminação e contra seu incitamento.","usage":"Diferencie igualdade formal de barreiras concretas de acesso à proteção jurídica.","source":"Art. 7 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-008","title":"Recurso efetivo contra violações","text":"Toda pessoa tem direito a recurso efetivo perante os tribunais nacionais competentes por violações de direitos fundamentais.","usage":"Fundamente canais acessíveis de denúncia e assistência jurídica, identificando quem pode implementá-los.","source":"Art. 8 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Violência"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-009","title":"Proteção contra prisão arbitrária","text":"A declaração repudia prisão, detenção e exílio arbitrários.","usage":"Ao discutir segurança pública, associe prevenção de abusos às garantias do Estado de Direito.","source":"Art. 9 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Violência","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-010","title":"Julgamento justo e independente","text":"O julgamento de direitos, deveres e acusações penais deve ocorrer com equidade por tribunal independente e imparcial.","usage":"Problematize condenações nas redes sem apuração, sem equiparar toda crítica pública a um julgamento penal.","source":"Art. 10 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-011","title":"Presunção de inocência","text":"A pessoa acusada tem direito à presunção de inocência e às garantias de defesa até a prova legal de culpa.","usage":"Discuta linchamentos e exposição de suspeitos; explique a diferença entre investigação e condenação.","source":"Art. 11 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Violência"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-012","title":"Vida privada e reputação","text":"A declaração protege contra interferências arbitrárias na vida privada, família, domicílio e correspondência, e contra ataques à honra.","usage":"Relacione exposição digital indevida à proteção da intimidade e proponha educação midiática e canais de proteção.","source":"Art. 12 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-013","title":"Liberdade de circulação","text":"Há direito de circulação e residência no interior de um Estado, bem como de sair de qualquer país e regressar ao próprio.","usage":"Aborde deslocamentos e mobilidade sem afirmar que o artigo garante entrada irrestrita em qualquer outro país.","source":"Art. 13 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-014","title":"Busca de asilo","text":"Em caso de perseguição, a declaração reconhece o direito de procurar e de beneficiar de asilo em outros países, com ressalvas expressas.","usage":"Humanize o debate sobre refugiados; diferencie perseguição, migração econômica e regras de reconhecimento do refúgio.","source":"Art. 14 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-015","title":"Direito à nacionalidade","text":"Toda pessoa tem direito a uma nacionalidade e não deve ser arbitrariamente privada dela ou do direito de mudá-la.","usage":"Explique por que a apatridia pode dificultar a proteção de direitos e o acesso a serviços.","source":"Art. 15 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-016","title":"Consentimento e igualdade no casamento","text":"A declaração prevê livre e pleno consentimento dos futuros cônjuges e igualdade de direitos no casamento e na dissolução.","usage":"Discuta casamento forçado e autonomia, sem usar o documento como fonte única sobre a legislação brasileira atual.","source":"Art. 16 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Minorias","Violência"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-017","title":"Direito à propriedade","text":"A declaração reconhece propriedade individual ou coletiva e repudia sua privação arbitrária.","usage":"Discuta segurança patrimonial junto das regras constitucionais brasileiras sobre função social, evitando absolutizar um só direito.","source":"Art. 17 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-018","title":"Liberdade de pensamento e religião","text":"Liberdade de pensamento, consciência e religião inclui mudar de crença e manifestá-la individual ou coletivamente.","usage":"Fundamente o respeito a diferentes crenças e à ausência de religião em uma sociedade plural.","source":"Art. 18 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-019","title":"Expressão e acesso à informação","text":"A liberdade de opinião e expressão inclui procurar, receber e transmitir informações e ideias por diferentes meios.","usage":"Associe acesso à informação à participação cidadã e discuta responsabilidades sem inventar proibição genérica de opinião.","source":"Art. 19 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-020","title":"Reunião e associação pacíficas","text":"A declaração protege reunião e associação pacíficas e veda obrigar alguém a pertencer a uma associação.","usage":"Explique o papel de organizações civis na defesa de direitos e no debate público.","source":"Art. 20 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-021","title":"Participação política","text":"A declaração reconhece participação no governo, acesso igual a funções públicas e eleições periódicas genuínas.","usage":"Discuta representação política e barreiras à participação para além do momento de votar.","source":"Art. 21 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-022","title":"Segurança social e dignidade","text":"A segurança social e a realização de direitos econômicos, sociais e culturais são relacionadas à dignidade e ao livre desenvolvimento.","usage":"Fundamente proteção social sem tratar a declaração como descrição de um benefício brasileiro específico.","source":"Art. 22 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-023","title":"Trabalho e remuneração justa","text":"O artigo trata de trabalho, livre escolha, condições justas, proteção contra desemprego, remuneração e organização sindical.","usage":"Analise precarização ou desigualdade salarial, explicitando o contexto e evitando supor que o direito já esteja realizado.","source":"Art. 23 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Trabalho","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-024","title":"Repouso e lazer","text":"O direito a repouso e lazer inclui limitação razoável da jornada e férias periódicas remuneradas.","usage":"Relacione excesso de trabalho a saúde e convivência; não atribua ao artigo uma jornada numérica específica.","source":"Art. 24 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Trabalho","Saúde"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-025","title":"Condições de vida e proteção social","text":"O artigo relaciona nível de vida adequado a alimentação, vestuário, habitação, cuidados médicos e serviços sociais.","usage":"Mostre que saúde exige condições materiais e proteção social, não apenas decisões individuais.","source":"Art. 25 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-026","title":"Educação e desenvolvimento humano","text":"A declaração reconhece a educação e orienta-a ao desenvolvimento da personalidade e ao respeito aos direitos humanos.","usage":"Fundamente inclusão e formação cidadã; diferencie etapas de ensino e condições de gratuidade previstas no texto.","source":"Art. 26 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-027","title":"Cultura e benefícios da ciência","text":"O artigo assegura participação na vida cultural, fruição das artes e participação no progresso científico e seus benefícios.","usage":"Conecte exclusão cultural ou digital à distribuição desigual de oportunidades de participação.","source":"Art. 27 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cultura","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-028","title":"Ordem que permita realizar direitos","text":"A declaração reconhece o direito a uma ordem social e internacional em que seus direitos possam ser plenamente realizados.","usage":"Relacione cooperação e instituições à efetivação de direitos, evitando usar o texto como prova causal de uma política.","source":"Art. 28 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-029","title":"Deveres perante a comunidade","text":"A declaração relaciona desenvolvimento pessoal à comunidade e prevê limites legais orientados aos direitos de outras pessoas e ao bem comum.","usage":"Discuta responsabilidade coletiva sem justificar restrições arbitrárias de liberdades.","source":"Art. 29 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Cidadania","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-030","title":"Direitos não autorizam destruir direitos","text":"Nenhuma disposição da declaração pode ser interpretada como direito de destruir os direitos e liberdades que ela reconhece.","usage":"Responda ao uso de uma liberdade como pretexto para eliminar a dignidade ou os direitos de terceiros.","source":"Art. 30 — fonte primária para consulta.","sourceURL":"https://www.ohchr.org/en/human-rights/universal-declaration/translations/portuguese","category":"Leis e direitos","axes":["Violência","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-031","title":"ODS 1 — Erradicação da pobreza","text":"A Agenda 2030 inclui acabar com a pobreza em todas as suas formas, em todos os lugares.","usage":"Relacione proteção social e acesso a recursos à superação de privações; defina qual dimensão da pobreza está analisando.","source":"Objetivo 1 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Cidadania","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-032","title":"ODS 2 — Fome zero e agricultura sustentável","text":"O objetivo articula combate à fome, segurança alimentar, melhoria da nutrição e agricultura sustentável.","usage":"Conecte produção de alimentos, distribuição e acesso econômico, sem reduzir a fome à falta de produção.","source":"Objetivo 2 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Saúde","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-033","title":"ODS 3 — Saúde e bem-estar","text":"A Agenda 2030 propõe vida saudável e bem-estar para todas as pessoas, em todas as idades.","usage":"Fundamente prevenção e acesso a cuidados ao longo da vida, indicando qual obstáculo sua proposta enfrenta.","source":"Objetivo 3 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-034","title":"ODS 4 — Educação de qualidade","text":"O objetivo propõe educação inclusiva, equitativa e de qualidade, além de oportunidades de aprendizagem ao longo da vida.","usage":"Analise permanência, aprendizagem ou acessibilidade, e não apenas o número de matrículas.","source":"Objetivo 4 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-035","title":"ODS 5 — Igualdade de gênero","text":"A Agenda 2030 inclui igualdade de gênero e empoderamento de mulheres e meninas.","usage":"Associe divisão do cuidado, violência ou desigualdade de oportunidades ao eixo específico do tema.","source":"Objetivo 5 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Minorias","Violência","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-036","title":"ODS 6 — Água potável e saneamento","text":"O objetivo reúne disponibilidade e gestão sustentável de água e saneamento para todas as pessoas.","usage":"Mostre como infraestrutura de saneamento une saúde pública, dignidade e proteção ambiental.","source":"Objetivo 6 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Saúde","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-037","title":"ODS 7 — Energia limpa e acessível","text":"A agenda prevê acesso confiável, sustentável, moderno e a preço acessível à energia.","usage":"Discuta transição energética incluindo desigualdade de acesso, sem tratar toda fonte como isenta de impactos.","source":"Objetivo 7 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Meio Ambiente","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-038","title":"ODS 8 — Trabalho decente","text":"O objetivo articula crescimento econômico inclusivo e sustentável, emprego pleno e produtivo e trabalho decente.","usage":"Diferencie criação de ocupações de qualidade do trabalho; explique condições, proteção e direitos.","source":"Objetivo 8 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Trabalho","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-039","title":"ODS 9 — Infraestrutura e inovação","text":"A agenda associa infraestrutura resiliente, industrialização inclusiva e sustentável e inovação.","usage":"Relacione conectividade e ciência à redução de desigualdades territoriais, não apenas ao consumo de aparelhos.","source":"Objetivo 9 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Tecnologia","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-040","title":"ODS 10 — Redução das desigualdades","text":"O objetivo propõe reduzir desigualdades dentro dos países e entre eles.","usage":"Identifique uma desigualdade concreta e explique por que medidas universais podem precisar de instrumentos inclusivos.","source":"Objetivo 10 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-041","title":"ODS 11 — Cidades sustentáveis","text":"A agenda orienta a tornar cidades e assentamentos inclusivos, seguros, resilientes e sustentáveis.","usage":"Relacione moradia, mobilidade e prevenção de riscos ao planejamento urbano.","source":"Objetivo 11 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Cidadania","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-042","title":"ODS 12 — Consumo e produção responsáveis","text":"O objetivo trata de padrões sustentáveis de produção e consumo.","usage":"Discuta resíduos ao longo da cadeia produtiva, compartilhando responsabilidades entre Estado, empresas e consumidores.","source":"Objetivo 12 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Meio Ambiente","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-043","title":"ODS 13 — Ação climática","text":"A agenda convoca medidas urgentes para combater a mudança do clima e seus impactos.","usage":"Distinga mitigação das emissões e adaptação aos impactos; proponha uma medida adequada ao recorte do tema.","source":"Objetivo 13 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Meio Ambiente","Saúde"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-044","title":"ODS 14 — Vida na água","text":"O objetivo aborda conservação e uso sustentável dos oceanos, mares e recursos marinhos.","usage":"Relacione poluição e pesca à proteção dos ecossistemas e aos modos de vida de comunidades costeiras.","source":"Objetivo 14 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Meio Ambiente","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-045","title":"ODS 15 — Vida terrestre","text":"A agenda trata de ecossistemas terrestres, florestas, desertificação, degradação do solo e biodiversidade.","usage":"Conecte desmatamento e conservação à manutenção de serviços ecossistêmicos e de territórios.","source":"Objetivo 15 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Meio Ambiente","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-046","title":"ODS 16 — Paz, justiça e instituições eficazes","text":"O objetivo reúne sociedades pacíficas e inclusivas, acesso à justiça e instituições eficazes, responsáveis e inclusivas.","usage":"Associe transparência e acesso à justiça à confiança institucional, apresentando um mecanismo concreto.","source":"Objetivo 16 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Violência","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-047","title":"ODS 17 — Parcerias e meios de implementação","text":"A agenda prevê fortalecer meios de implementação e a parceria global para o desenvolvimento sustentável.","usage":"Fundamente cooperação entre instituições, especificando atribuições em vez de sugerir uma parceria vaga.","source":"Objetivo 17 — fonte primária para consulta.","sourceURL":"https://brasil.un.org/pt-br/sdgs","category":"Agendas e documentos","axes":["Cidadania","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Meta da Agenda 2030, não dado sobre resultados já alcançados. Não atribua percentuais nem prazo nacional diferente sem fonte."},{"id":"doc-048","title":"Dignidade como fundamento constitucional","text":"A dignidade da pessoa humana é um dos fundamentos da República brasileira.","usage":"Use como parâmetro para avaliar uma prática que desumaniza um grupo e mostre sua consequência concreta.","source":"Art. 1º, III — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-049","title":"Reduzir desigualdades e combater preconceitos","text":"Entre os objetivos da República estão reduzir desigualdades sociais e regionais e promover o bem de todos sem discriminação.","usage":"Conecte desigualdade territorial ou preconceito a um compromisso constitucional, distinguindo objetivo e realização.","source":"Art. 3º, III e IV — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-050","title":"Liberdade de consciência e crença","text":"A Constituição protege liberdade de consciência e crença e o livre exercício dos cultos religiosos, nos termos do dispositivo.","usage":"Fundamente prevenção da intolerância religiosa e proteção da pluralidade de crenças.","source":"Art. 5º, VI — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-051","title":"Intimidade, vida privada, honra e imagem","text":"A Constituição protege intimidade, vida privada, honra e imagem e prevê indenização por sua violação.","usage":"Discuta exposição indevida de pessoas sem confundir qualquer divulgação de interesse público com violação automática.","source":"Art. 5º, X — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-052","title":"Acesso à informação","text":"A Constituição assegura acesso à informação e protege o sigilo da fonte quando necessário ao exercício profissional.","usage":"Relacione jornalismo e informação ao debate público, com cuidado para não prometer acesso irrestrito a dados sigilosos.","source":"Art. 5º, XIV — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-053","title":"Acesso ao Judiciário","text":"A lei não pode excluir da apreciação judicial lesão ou ameaça a direito.","usage":"Discuta assistência jurídica e barreiras de acesso à justiça, diferenciando garantia formal e capacidade real de utilizá-la.","source":"Art. 5º, XXXV — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-054","title":"Assistência jurídica a quem necessita","text":"A Constituição prevê assistência jurídica integral e gratuita aos que comprovarem insuficiência de recursos.","usage":"Proponha ampliação de orientação jurídica e acesso à Defensoria, respeitando competências e condições legais.","source":"Art. 5º, LXXIV — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-055","title":"Limitação constitucional da jornada","text":"O texto constitucional prevê duração normal de trabalho de até oito horas diárias e quarenta e quatro semanais, com possibilidades de compensação ou redução previstas.","usage":"Discuta tempo de trabalho e descanso sem ignorar regimes especiais e regras próprias de cada vínculo.","source":"Art. 7º, XIII — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Trabalho","Saúde"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-056","title":"Vedação de diferenças discriminatórias no emprego","text":"O dispositivo proíbe diferenças de salários, funções e critérios de admissão por motivo de sexo, idade, cor ou estado civil.","usage":"Relacione discriminação no trabalho a um parâmetro jurídico explícito e proponha fiscalização ou transparência.","source":"Art. 7º, XXX — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Trabalho","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-057","title":"Princípios da administração pública","text":"Legalidade, impessoalidade, moralidade, publicidade e eficiência orientam a administração pública.","usage":"Avalie filas, atendimento ou opacidade de decisões com base no princípio pertinente, sem usar a lista apenas como enfeite.","source":"Art. 37, caput — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cidadania","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-058","title":"Defesa do meio ambiente na ordem econômica","text":"A defesa do meio ambiente é um dos princípios da ordem econômica constitucional.","usage":"Mostre que desenvolvimento econômico e exigências ambientais devem ser pensados conjuntamente.","source":"Art. 170, VI — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Meio Ambiente","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-059","title":"Política urbana e bem-estar","text":"A política de desenvolvimento urbano, executada pelo poder público municipal segundo diretrizes legais, busca ordenar funções sociais da cidade e garantir bem-estar.","usage":"Associe mobilidade, moradia ou segregação ao planejamento municipal e aos instrumentos urbanísticos.","source":"Art. 182 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cidadania","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-060","title":"Saúde como direito e dever estatal","text":"O dispositivo relaciona saúde a políticas sociais e econômicas, redução de riscos e acesso universal e igualitário a ações e serviços.","usage":"Explique por que prevenção e condições de vida complementam a oferta de atendimento médico.","source":"Art. 196 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-061","title":"Participação da comunidade no SUS","text":"A participação da comunidade é uma diretriz constitucional do sistema público de saúde.","usage":"Proponha fortalecimento de conselhos e escuta social, em vez de sugerir que decisões dependam apenas de especialistas.","source":"Art. 198, III — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-062","title":"Permanência e qualidade na educação","text":"Os princípios do ensino incluem igualdade de condições para acesso e permanência e garantia de padrão de qualidade.","usage":"Mostre que matrícula isolada não resolve evasão, falta de acessibilidade ou aprendizagem insuficiente.","source":"Art. 206, I e VII — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-063","title":"Atendimento educacional especializado","text":"A Constituição prevê atendimento educacional especializado às pessoas com deficiência, preferencialmente na rede regular de ensino.","usage":"Discuta apoio e acessibilidade sem defender segregação automática como resposta à inclusão.","source":"Art. 208, III — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-064","title":"Direitos culturais e acesso à cultura","text":"O Estado deve garantir o exercício dos direitos culturais e acesso às fontes da cultura nacional, apoiando e incentivando a valorização e difusão das manifestações culturais.","usage":"Conecte desigualdade de acesso a equipamentos culturais e reconhecimento de manifestações locais.","source":"Art. 215 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-065","title":"Patrimônio material e imaterial","text":"O patrimônio cultural brasileiro inclui bens materiais e imateriais ligados à identidade, à ação e à memória dos grupos formadores da sociedade.","usage":"Fundamente a proteção de saberes, festas ou espaços de memória para além de monumentos arquitetônicos.","source":"Art. 216 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-066","title":"Prioridade dos direitos de crianças e adolescentes","text":"Família, sociedade e Estado devem assegurar com absoluta prioridade direitos de crianças, adolescentes e jovens, nos termos constitucionais.","usage":"Defina responsabilidades complementares no enfrentamento de violência ou exclusão, evitando culpar só as famílias.","source":"Art. 227 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Educação","Violência","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-067","title":"Direitos dos povos indígenas","text":"A Constituição reconhece organização social, costumes, línguas, crenças, tradições e direitos originários dos povos indígenas sobre terras tradicionalmente ocupadas.","usage":"Discuta território e continuidade cultural sem tratar povos indígenas como um grupo homogêneo ou preso ao passado.","source":"Art. 231 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm","category":"Leis e direitos","axes":["Minorias","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-068","title":"Desenvolvimento com liberdade e dignidade","text":"O ECA protege direitos fundamentais e oportunidades para o desenvolvimento físico, mental, moral, espiritual e social em condições de liberdade e dignidade.","usage":"Analise como uma barreira específica compromete o desenvolvimento de crianças e adolescentes.","source":"Art. 3º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-069","title":"Responsabilidade compartilhada e prioridade","text":"Família, comunidade, sociedade e poder público têm deveres na efetivação prioritária dos direitos de crianças e adolescentes.","usage":"Distribua atribuições concretas entre escola, família e serviços públicos na proposta de intervenção.","source":"Art. 4º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Cidadania","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-070","title":"Proteção contra negligência e discriminação","text":"O ECA veda negligência, discriminação, exploração, violência, crueldade e opressão contra crianças e adolescentes.","usage":"Relacione naturalização de uma violência à necessidade de proteção e de canais acessíveis de denúncia.","source":"Art. 5º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Violência","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-071","title":"Proteção da vida e da saúde na infância","text":"Crianças e adolescentes têm direito à proteção à vida e à saúde por políticas que permitam nascimento e desenvolvimento sadios e harmoniosos.","usage":"Fundamente prevenção e cuidado continuado sem restringir a saúde infantil ao atendimento de emergência.","source":"Art. 7º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Saúde","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-072","title":"Acesso integral à saúde pelo SUS","text":"O ECA assegura acesso integral às linhas de cuidado voltadas à saúde da criança e do adolescente por intermédio do SUS.","usage":"Discuta barreiras de acesso e continuidade do cuidado, inclusive para crianças com deficiência.","source":"Art. 11 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Saúde","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-073","title":"Liberdade, respeito e dignidade","text":"Crianças e adolescentes são sujeitos de direitos civis, humanos e sociais e titulares de liberdade, respeito e dignidade.","usage":"Conteste a ideia de que a infância não tem voz, sem ignorar proteção e responsabilidades adequadas à idade.","source":"Art. 15 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-074","title":"Brincar, participar e expressar-se","text":"Entre as dimensões da liberdade estão opinião, expressão, crença, brincar e participar da vida familiar e comunitária, sem discriminação.","usage":"Associe falta de espaços de lazer à limitação de experiências formativas na infância.","source":"Art. 16 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Educação","Cultura"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-075","title":"Integridade e preservação da imagem","text":"O direito ao respeito abrange integridade física, psíquica e moral e preservação de imagem, identidade, autonomia, valores e espaços pessoais.","usage":"Analise exposição infantil nas redes ou humilhação escolar com foco na proteção da pessoa, não só dos dados.","source":"Art. 17 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Tecnologia","Violência"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-076","title":"Educar sem castigo físico","text":"O ECA assegura educação e cuidado sem castigo físico ou tratamento cruel ou degradante como correção, disciplina ou educação.","usage":"Proponha orientação e apoio a responsáveis e profissionais, distinguindo disciplina de violência.","source":"Art. 18-A — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Violência","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-077","title":"Convivência familiar e comunitária","text":"A convivência familiar e comunitária é um direito da criança e do adolescente, com criação na família e excepcionalmente em família substituta.","usage":"Discuta acolhimento e redes de proteção sem associar pobreza automaticamente à incapacidade familiar.","source":"Art. 19 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-078","title":"Pobreza não justifica perda do poder familiar","text":"A falta ou carência de recursos materiais não constitui motivo suficiente para perda ou suspensão do poder familiar.","usage":"Problematize a criminalização da pobreza e proponha apoio material e serviços de proteção social.","source":"Art. 23 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-079","title":"Educação e participação estudantil","text":"O direito à educação inclui igualdade de acesso e permanência, respeito por educadores e participação em entidades estudantis.","usage":"Conecte evasão e clima escolar a acolhimento e participação, em vez de culpar apenas o aluno.","source":"Art. 53 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Educação","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-080","title":"Cultura, esporte e lazer na infância","text":"Municípios, com apoio de Estados e União, devem estimular e facilitar recursos e espaços para programas culturais, esportivos e de lazer voltados à infância e juventude.","usage":"Defina o poder público municipal como agente pertinente em uma proposta sobre espaços de convivência.","source":"Art. 59 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Cultura","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-081","title":"Dever de prevenir violações","text":"É dever de todos prevenir ameaça ou violação dos direitos da criança e do adolescente.","usage":"Justifique ações preventivas articuladas à rede de proteção, sem reduzir prevenção a campanhas isoladas.","source":"Art. 70 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Violência","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-082","title":"Conselho Tutelar como órgão de proteção","text":"O Conselho Tutelar é órgão permanente, autônomo e não jurisdicional encarregado de zelar pelo cumprimento dos direitos previstos no ECA.","usage":"Use o agente correto em intervenções de proteção; não o apresente como tribunal ou responsável por condenar pessoas.","source":"Art. 131 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8069.htm","category":"Leis e direitos","axes":["Violência","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-083","title":"Deficiência e barreiras à participação","text":"A Lei Brasileira de Inclusão relaciona impedimentos de longo prazo à interação com barreiras que podem obstruir participação plena e efetiva em igualdade de condições.","usage":"Desloque o argumento da suposta incapacidade individual para barreiras sociais e ambientais concretas.","source":"Art. 2º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-084","title":"Acessibilidade não é favor","text":"A acessibilidade envolve uso com segurança e autonomia de espaços, equipamentos, transportes, informação, comunicação e serviços.","usage":"Mostre por que inclusão exige desenho de ambientes e serviços, não apenas boa vontade individual.","source":"Art. 3º, I — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Minorias","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-085","title":"Barreiras atitudinais","text":"A lei identifica atitudes e comportamentos que impedem ou prejudicam a participação social em igualdade de condições como barreiras atitudinais.","usage":"Discuta capacitismo em práticas e expectativas; proponha formação acompanhada de mudanças institucionais.","source":"Art. 3º, IV — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Minorias","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-086","title":"Igualdade e não discriminação por deficiência","text":"A pessoa com deficiência tem direito à igualdade de oportunidades e não deve sofrer discriminação, inclusive por recusa de adaptações razoáveis e tecnologias assistivas.","usage":"Relacione uma barreira concreta a adaptações possíveis e responsabilidades de quem presta o serviço.","source":"Art. 4º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-087","title":"Deficiência não elimina capacidade civil","text":"O dispositivo afirma que a deficiência não afeta a plena capacidade civil da pessoa, nos termos dos direitos enumerados.","usage":"Conteste a infantilização de adultos com deficiência sem ignorar os instrumentos legais de apoio quando necessários.","source":"Art. 6º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-088","title":"Efetivação compartilhada de direitos","text":"Estado, sociedade e família têm deveres na efetivação prioritária dos direitos das pessoas com deficiência.","usage":"Construa uma intervenção com agentes e ações articulados, evitando transferir toda responsabilidade à família.","source":"Art. 8º — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Minorias","Saúde"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-089","title":"Educação inclusiva ao longo da vida","text":"A educação da pessoa com deficiência deve contar com sistema inclusivo em todos os níveis e aprendizado ao longo de toda a vida.","usage":"Discuta acesso, permanência e aprendizagem em conjunto, respeitando características e necessidades individuais.","source":"Art. 27 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-090","title":"Acessibilidade em seleções educacionais","text":"O dispositivo prevê medidas de acessibilidade em processos seletivos para ingresso e permanência no ensino superior e na educação profissional e tecnológica.","usage":"Mostre como adaptação de provas e recursos de acessibilidade reduzem barreiras sem significar privilégio arbitrário.","source":"Art. 30 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Educação","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-091","title":"Trabalho em ambiente acessível e inclusivo","text":"A pessoa com deficiência tem direito a trabalho de livre escolha e aceitação em ambiente acessível e inclusivo, com igualdade de oportunidades.","usage":"Diferencie contratação formal de inclusão efetiva no cotidiano do trabalho.","source":"Art. 34 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Trabalho","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-092","title":"Acessibilidade nos sites","text":"A lei exige acessibilidade nos sítios da internet mantidos por empresas com sede ou representação comercial no país ou por órgãos de governo, nos termos do dispositivo.","usage":"Inclua navegação por teclado, leitura por tecnologia assistiva e informação acessível em propostas sobre cidadania digital.","source":"Art. 63 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13146.htm","category":"Leis e direitos","axes":["Tecnologia","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-093","title":"Finalidade no tratamento de dados","text":"O tratamento deve atender a propósitos legítimos, específicos, explícitos e informados ao titular.","usage":"Problematize a coleta de informações sem explicação clara de para que serão usadas.","source":"Art. 6º, I — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-094","title":"Adequação ao contexto da coleta","text":"O tratamento deve ser compatível com as finalidades informadas ao titular e com o contexto em que ocorre.","usage":"Analise mudança de uso de dados entre um serviço solicitado e uma finalidade distinta.","source":"Art. 6º, II — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-095","title":"Necessidade e minimização de dados","text":"O princípio da necessidade limita o tratamento ao mínimo necessário, com dados pertinentes, proporcionais e não excessivos.","usage":"Proponha reduzir cadastros desnecessários e explique como isso diminui exposição de informações pessoais.","source":"Art. 6º, III — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-096","title":"Livre acesso do titular","text":"O titular deve poder consultar de forma facilitada e gratuita a forma e a duração do tratamento e a integralidade de seus dados.","usage":"Fundamente mecanismos claros para a pessoa conhecer o que uma instituição guarda sobre ela.","source":"Art. 6º, IV — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-097","title":"Qualidade dos dados","text":"A lei exige exatidão, clareza, relevância e atualização dos dados conforme a necessidade e a finalidade do tratamento.","usage":"Discuta decisões injustas produzidas por cadastros desatualizados e a importância de correção de informações.","source":"Art. 6º, V — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-098","title":"Transparência no uso de dados","text":"O titular deve receber informações claras, precisas e acessíveis sobre o tratamento e seus agentes, observados os segredos comercial e industrial.","usage":"Critique termos incompreensíveis e proponha comunicação acessível, sem prometer divulgação irrestrita de todo segredo empresarial.","source":"Art. 6º, VI — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-099","title":"Segurança de informações pessoais","text":"O princípio da segurança prevê medidas técnicas e administrativas contra acesso não autorizado e situações acidentais ou ilícitas de destruição, perda, alteração ou divulgação.","usage":"Associe proteção de dados a práticas institucionais, não só ao cuidado individual com senhas.","source":"Art. 6º, VII — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-100","title":"Prevenção de danos com dados","text":"O tratamento deve incorporar medidas para prevenir danos decorrentes do uso de dados pessoais.","usage":"Defenda avaliação de riscos antes de implantar cadastros ou sistemas que possam afetar grupos vulneráveis.","source":"Art. 6º, VIII — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-101","title":"Não discriminação por dados","text":"A LGPD proíbe tratamento para fins discriminatórios ilícitos ou abusivos.","usage":"Discuta seleção automatizada ou publicidade excludente, explicando o risco sem afirmar que todo algoritmo discrimina necessariamente.","source":"Art. 6º, IX — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-102","title":"Responsabilização e prestação de contas","text":"Os agentes devem demonstrar adoção de medidas eficazes e capazes de comprovar observância e cumprimento das normas de proteção de dados.","usage":"Proponha auditoria e responsabilidades verificáveis em vez de apenas promessas genéricas de segurança.","source":"Art. 6º, X — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2018/lei/l13709.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-103","title":"Marco Civil da Internet","text":"A lei estabelece princípios, garantias, direitos e deveres para o uso da internet no Brasil, incluindo liberdade de expressão e proteção da privacidade.","usage":"Fundamente cidadania digital e proteção de usuários, diferenciando este marco geral das regras específicas da LGPD.","source":"Lei 12.965/2014 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2014/lei/l12965.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-104","title":"Política Nacional do Meio Ambiente","text":"A política organiza objetivos e instrumentos de proteção ambiental, entre eles avaliação de impactos e licenciamento de atividades potencialmente poluidoras.","usage":"Relacione prevenção de danos a instrumentos institucionais, sem afirmar que licenciamento elimina todo risco.","source":"Lei 6.938/1981 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l6938.htm","category":"Leis e direitos","axes":["Meio Ambiente","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-105","title":"Responsabilidade compartilhada pelos resíduos","text":"A Política Nacional de Resíduos Sólidos institui responsabilidade compartilhada pelo ciclo de vida dos produtos e prevê logística reversa em hipóteses legais.","usage":"Distribua ações entre fabricantes, comerciantes, consumidores e poder público; não reduza a solução a reciclar em casa.","source":"Lei 12.305/2010 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12305.htm","category":"Leis e direitos","axes":["Meio Ambiente","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-106","title":"Educação ambiental permanente","text":"A Política Nacional de Educação Ambiental trata a educação ambiental como componente essencial e permanente da educação nacional, em caráter formal e não formal.","usage":"Proponha formação integrada a práticas locais, sem inventar a exigência de uma disciplina isolada em todos os níveis.","source":"Lei 9.795/1999 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l9795.htm","category":"Leis e direitos","axes":["Educação","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-107","title":"Saúde e seus determinantes sociais","text":"A Lei Orgânica da Saúde reconhece fatores como alimentação, moradia, saneamento, ambiente, trabalho, renda e educação como determinantes e condicionantes da saúde.","usage":"Explique uma cadeia causal entre condição de vida e adoecimento, evitando responsabilizar apenas o indivíduo.","source":"Lei 8.080/1990 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8080.htm","category":"Leis e direitos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-108","title":"Controle social na saúde","text":"A lei disciplina participação da comunidade na gestão do SUS por conferências e conselhos de saúde, além de transferências intergovernamentais.","usage":"Inclua conselhos de saúde em propostas de acompanhamento e discussão de políticas, sem lhes atribuir funções clínicas.","source":"Lei 8.142/1990 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8142.htm","category":"Leis e direitos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-109","title":"Estatuto da Pessoa Idosa","text":"O estatuto protege direitos das pessoas com idade igual ou superior a sessenta anos e estabelece deveres de proteção e prioridade.","usage":"Relacione etarismo a autonomia e acesso a direitos; não trate todas as pessoas idosas como dependentes.","source":"Lei 10.741/2003 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/2003/l10.741.htm","category":"Leis e direitos","axes":["Saúde","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-110","title":"Lei Maria da Penha","text":"A lei cria mecanismos de enfrentamento da violência doméstica e familiar contra a mulher e prevê medidas de assistência e proteção.","usage":"Diferencie prevenção, acolhimento e responsabilização; não reduza violência à agressão física nem prometa proteção automática sem implementação.","source":"Lei 11.340/2006 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11340.htm","category":"Leis e direitos","axes":["Violência","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-111","title":"Atendimento a vítimas de violência sexual","text":"A lei dispõe sobre atendimento obrigatório e integral de pessoas em situação de violência sexual nos hospitais integrantes da rede do SUS.","usage":"Fundamente acolhimento e acesso imediato a cuidados, evitando condicionar atendimento a juízos morais sobre a vítima.","source":"Lei 12.845/2013 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/lei/l12845.htm","category":"Leis e direitos","axes":["Saúde","Violência"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-112","title":"Estatuto da Juventude","text":"O estatuto dispõe sobre direitos de jovens entre quinze e vinte e nove anos e princípios das políticas públicas de juventude, observadas as regras de proteção dos adolescentes.","usage":"Discuta transição escola-trabalho e participação juvenil sem tratar toda a faixa etária como socialmente homogênea.","source":"Lei 12.852/2013 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2013/lei/l12852.htm","category":"Leis e direitos","axes":["Educação","Trabalho","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-113","title":"Estatuto da Igualdade Racial","text":"O estatuto destina-se à garantia de igualdade de oportunidades à população negra, defesa de direitos étnicos e combate à discriminação e intolerância étnica.","usage":"Relacione enfrentamento do racismo a medidas em saúde, educação, cultura ou trabalho, conforme o tema.","source":"Lei 12.288/2010 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2010/lei/l12288.htm","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-114","title":"Responsabilização por discriminação racial","text":"A lei define crimes resultantes de discriminação ou preconceito de raça, cor, etnia, religião ou procedência nacional, com alterações posteriores.","usage":"Distingua responsabilização penal de medidas educativas e preventivas; não invente penas ou enquadramentos para situações não analisadas.","source":"Lei 7.716/1989 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l7716.htm","category":"Leis e direitos","axes":["Minorias","Violência"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-115","title":"História e cultura afro-brasileira na escola","text":"A lei alterou a LDB para incluir a obrigatoriedade do ensino de história e cultura afro-brasileira nos estabelecimentos de ensino fundamental e médio.","usage":"Discuta valorização de contribuições negras e formação docente, sem restringir o conteúdo a datas comemorativas.","source":"Lei 10.639/2003 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/2003/l10.639.htm","category":"Leis e direitos","axes":["Educação","Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-116","title":"História e cultura indígena no currículo","text":"A lei ampliou a previsão da LDB para incluir história e cultura afro-brasileira e indígena no ensino fundamental e médio, público e privado.","usage":"Proponha tratamento plural e contínuo dos povos indígenas, evitando estereótipos de uma única cultura indígena.","source":"Lei 11.645/2008 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2008/lei/l11645.htm","category":"Leis e direitos","axes":["Educação","Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-117","title":"Educação além da preparação para o emprego","text":"A LDB relaciona educação ao pleno desenvolvimento do educando, ao preparo para o exercício da cidadania e à qualificação para o trabalho.","usage":"Defenda formação ampla e aprendizagem significativa, sem opor artificialmente cidadania e preparação profissional.","source":"Lei 9.394/1996 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l9394.htm","category":"Leis e direitos","axes":["Educação","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-118","title":"Saneamento como infraestrutura integrada","text":"A lei de diretrizes nacionais do saneamento básico abrange abastecimento de água, esgotamento sanitário, limpeza urbana e resíduos, e drenagem urbana, com atualizações posteriores.","usage":"Mostre por que saneamento não equivale apenas à água encanada e conecte infraestrutura à prevenção de doenças e enchentes.","source":"Lei 11.445/2007 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2007/lei/l11445.htm","category":"Leis e direitos","axes":["Saúde","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-119","title":"Proteção da vegetação nativa","text":"A lei dispõe sobre proteção da vegetação nativa e inclui instrumentos como áreas de preservação permanente e reserva legal.","usage":"Diferencie proteção de margens de rios e outras áreas especialmente protegidas das regras gerais de uso do solo; não invente percentuais universais.","source":"Lei 12.651/2012 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12651.htm","category":"Leis e direitos","axes":["Meio Ambiente","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-120","title":"Água, gestão e usos múltiplos","text":"A Política Nacional de Recursos Hídricos trata a água como bem de domínio público e recurso limitado com valor econômico; em escassez, prioriza consumo humano e dessedentação animal.","usage":"Discuta conflitos de uso e gestão participativa, sem confundir cobrança pelo uso com propriedade privada da água.","source":"Lei 9.433/1997 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l9433.htm","category":"Leis e direitos","axes":["Meio Ambiente","Saúde"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-121","title":"Unidades de conservação e suas diferenças","text":"O Sistema Nacional de Unidades de Conservação reúne grupos de proteção integral e de uso sustentável, com objetivos e regras distintos.","usage":"Evite afirmar que toda área protegida proíbe presença humana; relacione conservação a usos e direitos específicos.","source":"Lei 9.985/2000 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l9985.htm","category":"Leis e direitos","axes":["Meio Ambiente","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-122","title":"Proteção da Mata Atlântica","text":"A lei dispõe sobre utilização e proteção da vegetação nativa do Bioma Mata Atlântica, com critérios e condições definidos.","usage":"Fundamente fiscalização e recuperação de um bioma determinado, sem aplicar suas regras automaticamente a todos os biomas.","source":"Lei 11.428/2006 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2006/lei/l11428.htm","category":"Leis e direitos","axes":["Meio Ambiente","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-123","title":"Sanções por danos ambientais","text":"A lei trata de sanções penais e administrativas derivadas de condutas e atividades lesivas ao meio ambiente.","usage":"Discuta responsabilização junto de prevenção e reparação, sem presumir que toda infração tenha a mesma pena.","source":"Lei 9.605/1998 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l9605.htm","category":"Leis e direitos","axes":["Meio Ambiente","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-124","title":"Informação pública e transparência","text":"A Lei de Acesso à Informação disciplina acesso a informações públicas, com publicidade como regra e hipóteses legais de restrição.","usage":"Proponha dados acessíveis e resposta a pedidos para fiscalização cidadã, respeitando informações pessoais e sigilos previstos.","source":"Lei 12.527/2011 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2011/lei/l12527.htm","category":"Leis e direitos","axes":["Cidadania","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-125","title":"Direitos de usuários de serviços públicos","text":"A lei dispõe sobre participação, proteção e defesa dos direitos do usuário dos serviços públicos e prevê instrumentos como ouvidorias e avaliação.","usage":"Relacione melhoria de atendimento à escuta efetiva e à resposta institucional, não apenas à abertura de um formulário.","source":"Lei 13.460/2017 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2017/lei/l13460.htm","category":"Leis e direitos","axes":["Cidadania","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-126","title":"Consumidor, informação e publicidade","text":"O Código de Defesa do Consumidor prevê direitos à informação adequada e clara e proteção contra publicidade enganosa e abusiva.","usage":"Analise assimetria de informação e vulnerabilidade do consumidor, sem afirmar que toda publicidade é ilícita.","source":"Lei 8.078/1990 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l8078compilado.htm","category":"Leis e direitos","axes":["Tecnologia","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-127","title":"Biossegurança e avaliação de riscos","text":"A Lei de Biossegurança estabelece normas para atividades com organismos geneticamente modificados e seus derivados e organiza competências institucionais.","usage":"Mostre a importância de avaliação técnica e regulação, sem declarar que toda inovação genética é segura ou perigosa.","source":"Lei 11.105/2005 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2004-2006/2005/lei/l11105.htm","category":"Leis e direitos","axes":["Tecnologia","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-128","title":"Voluntariado não substitui política pública","text":"A lei disciplina serviço voluntário não remunerado, prestado por pessoa física a entidade pública ou instituição privada sem fins lucrativos nas finalidades previstas.","usage":"Inclua participação comunitária como complemento, sem substituir deveres estatais ou confundir voluntariado com emprego sem direitos.","source":"Lei 9.608/1998 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l9608.htm","category":"Leis e direitos","axes":["Cidadania","Trabalho"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-129","title":"Normas gerais de acessibilidade","text":"A lei estabelece normas e critérios básicos de promoção da acessibilidade de pessoas com deficiência ou mobilidade reduzida, com alterações posteriores.","usage":"Relacione barreiras urbanas e comunicacionais a planejamento e fiscalização, não apenas à instalação isolada de uma rampa.","source":"Lei 10.098/2000 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/l10098.htm","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-130","title":"Reconhecimento da Libras","text":"A lei reconhece a Língua Brasileira de Sinais como meio legal de comunicação e expressão e prevê apoio a seu uso e difusão.","usage":"Fundamente inclusão linguística de pessoas surdas; não diga que a lei tornou Libras a segunda língua oficial do Brasil.","source":"Lei 10.436/2002 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/2002/l10436.htm","category":"Leis e direitos","axes":["Educação","Minorias","Cultura"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-131","title":"Combate à intimidação sistemática","text":"A lei institui programa de combate à intimidação sistemática, caracterizada por violência física ou psicológica intencional e repetitiva, em contexto de desequilíbrio de poder.","usage":"Diferencie conflito pontual de bullying e articule prevenção, acolhimento e responsabilização adequados.","source":"Lei 13.185/2015 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13185.htm","category":"Leis e direitos","axes":["Violência","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-132","title":"Política Nacional de Educação Digital","text":"A política reúne eixos de inclusão digital, educação digital escolar, capacitação e especialização digital, e pesquisa e desenvolvimento em tecnologias da informação e comunicação.","usage":"Discuta formação crítica e competências digitais além da distribuição de dispositivos.","source":"Lei 14.533/2023 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14533.htm","category":"Leis e direitos","axes":["Educação","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-133","title":"Igualdade salarial entre mulheres e homens","text":"A lei dispõe sobre igualdade salarial e de critérios remuneratórios entre mulheres e homens e prevê instrumentos de transparência e fiscalização.","usage":"Associe combate à desigualdade remuneratória a acompanhamento institucional, sem inventar um percentual atual de diferença salarial.","source":"Lei 14.611/2023 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14611.htm","category":"Leis e direitos","axes":["Trabalho","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-134","title":"Estatuto da Cidade e função social","text":"O Estatuto da Cidade estabelece diretrizes da política urbana, incluindo direito a cidades sustentáveis e gestão democrática.","usage":"Fundamente participação no planejamento e acesso a moradia, saneamento, transporte e serviços, conforme o recorte urbano.","source":"Lei 10.257/2001 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/leis/leis_2001/l10257.htm","category":"Leis e direitos","axes":["Cidadania","Meio Ambiente"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-135","title":"Prevenção e redução de riscos de desastres","text":"A Política Nacional de Proteção e Defesa Civil articula prevenção, mitigação, preparação, resposta e recuperação em relação a desastres.","usage":"Mostre por que alertas e planejamento prévio devem acompanhar socorro e reconstrução após enchentes ou deslizamentos.","source":"Lei 12.608/2012 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2011-2014/2012/lei/l12608.htm","category":"Leis e direitos","axes":["Meio Ambiente","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-136","title":"Patrimônio genético e conhecimentos tradicionais","text":"A lei regula acesso ao patrimônio genético, proteção e acesso ao conhecimento tradicional associado e repartição de benefícios nas hipóteses previstas.","usage":"Relacione inovação e biodiversidade a direitos de comunidades detentoras de conhecimentos, evitando tratar esses saberes como recursos livres sem regras.","source":"Lei 13.123/2015 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2015-2018/2015/lei/l13123.htm","category":"Leis e direitos","axes":["Meio Ambiente","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-137","title":"Prevenção da automutilação e do suicídio","text":"A lei institui política nacional de prevenção da automutilação e do suicídio, incluindo promoção da saúde mental e acesso à atenção psicossocial.","usage":"Defenda acolhimento profissional e redes de cuidado; evite descrições de métodos ou explicações monocausais de sofrimento psíquico.","source":"Lei 13.819/2019 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2019/lei/l13819.htm","category":"Leis e direitos","axes":["Saúde","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial, não citação literal. Norma ou compromisso não prova cumprimento efetivo; consulte a redação vigente e o contexto da fonte."},{"id":"doc-138","title":"Patrimônio cultural imaterial","text":"A convenção da UNESCO trata da salvaguarda de práticas, representações, expressões, conhecimentos e técnicas reconhecidos pelas comunidades como parte de seu patrimônio cultural.","usage":"Fundamente valorização de tradições vivas com participação de seus detentores, sem congelar culturas no passado.","source":"Convenção de 2003 — fonte primária para consulta.","sourceURL":"https://www.unesco.org/en/legal-affairs/convention-safeguarding-intangible-cultural-heritage","category":"Históricos","axes":["Cultura","Minorias"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-139","title":"Prática de testes e estudo distribuído","text":"A revisão sobre técnicas de aprendizagem atribuiu alta utilidade à prática de testes e à prática distribuída em diferentes contextos de aprendizagem.","usage":"Discuta qualidade de estratégias de estudo; descreva condições e limites, sem prometer uma nota ou aplicar o resultado automaticamente a todo aluno.","source":"Dunlosky e colaboradores, 2013 — fonte primária para consulta.","sourceURL":"https://pubmed.ncbi.nlm.nih.gov/26173288/","category":"Pensadores e conceitos","axes":["Educação","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Síntese de pesquisa em contextos específicos; não garante resultado individual nem demonstra superioridade em qualquer situação."},{"id":"doc-140","title":"Efeito de testar a própria memória","text":"Nos experimentos relatados, testes de recuperação de textos favoreceram retenção tardia em comparação com estudo repetido em determinadas condições.","usage":"Fundamente recuperação ativa como estratégia de aprendizagem, distinguindo retenção experimental de uma garantia de desempenho no ENEM.","source":"Roediger e Karpicke, 2006 — fonte primária para consulta.","sourceURL":"https://pubmed.ncbi.nlm.nih.gov/16507066/","category":"Pensadores e conceitos","axes":["Educação","Tecnologia"],"kind":"Biblioteca ampliada · paráfrase","warning":"Síntese de pesquisa em contextos específicos; não garante resultado individual nem demonstra superioridade em qualquer situação."},{"id":"doc-141","title":"Espaçamento e retenção","text":"A revisão quantitativa examinou prática distribuída em tarefas de recordação verbal e mostrou que o intervalo de estudo se relaciona ao tempo até o teste.","usage":"Defenda continuidade e distribuição do estudo; não atribua ao trabalho uma sequência fixa universal de dias.","source":"Cepeda e colaboradores, 2006 — fonte primária para consulta.","sourceURL":"https://pubmed.ncbi.nlm.nih.gov/16719566/","category":"Pensadores e conceitos","axes":["Educação","Saúde"],"kind":"Biblioteca ampliada · paráfrase","warning":"Síntese de pesquisa em contextos específicos; não garante resultado individual nem demonstra superioridade em qualquer situação."},{"id":"doc-142","title":"Direito da criança de ser ouvida","text":"A Convenção sobre os Direitos da Criança reconhece o direito de expressar opiniões sobre questões que a afetem, com consideração de idade e maturidade.","usage":"Proponha escuta de estudantes em medidas de proteção e melhoria escolar, sem transferir a eles responsabilidades adultas.","source":"Convenção de 1989, art. 12 — fonte primária para consulta.","sourceURL":"https://www.unicef.org/brazil/convencao-sobre-os-direitos-da-crianca","category":"Leis e direitos","axes":["Educação","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-143","title":"Inclusão e participação em igualdade","text":"A Convenção sobre os Direitos das Pessoas com Deficiência orienta proteção de direitos e liberdades e respeito à dignidade, com autonomia, participação e acessibilidade.","usage":"Use como marco de direitos para contestar assistencialismo que exclua a pessoa das decisões sobre sua própria vida.","source":"Convenção promulgada pelo Decreto 6.949/2009 — fonte primária para consulta.","sourceURL":"https://www.planalto.gov.br/ccivil_03/_ato2007-2010/2009/decreto/d6949.htm","category":"Leis e direitos","axes":["Minorias","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-144","title":"Cooperação para enfrentar a mudança do clima","text":"O acordo busca manter o aumento da temperatura média global bem abaixo de dois graus Celsius e envidar esforços para limitá-lo a um grau e meio acima dos níveis pré-industriais.","usage":"Relacione compromissos climáticos a medidas concretas de mitigação e adaptação, sem confundir meta com temperatura já alcançada.","source":"Acordo de Paris, 2015 — fonte primária para consulta.","sourceURL":"https://unfccc.int/process-and-meetings/the-paris-agreement/the-paris-agreement","category":"Históricos","axes":["Meio Ambiente","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-145","title":"Rio-92 e agenda ambiental global","text":"A conferência realizada no Rio de Janeiro consolidou documentos e negociações internacionais sobre ambiente e desenvolvimento, incluindo Agenda 21 e Declaração do Rio.","usage":"Contextualize cooperação ambiental e responsabilidades políticas, distinguindo a Agenda 21 da posterior Agenda 2030.","source":"Conferência das Nações Unidas, 1992 — fonte primária para consulta.","sourceURL":"https://www.un.org/en/conferences/environment/rio1992","category":"Históricos","axes":["Meio Ambiente","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-146","title":"Trabalho infantil e proteção da infância","text":"A OIT distingue trabalho infantil prejudicial de atividades que não comprometem saúde, desenvolvimento ou escolarização, considerando idade e normas aplicáveis.","usage":"Discuta exploração e evasão sem tratar toda ajuda doméstica adequada à idade como equivalente ao trabalho infantil proibido.","source":"Organização Internacional do Trabalho — fonte primária para consulta.","sourceURL":"https://www.ilo.org/topics-and-sectors/child-labour","category":"Leis e direitos","axes":["Trabalho","Educação"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."},{"id":"doc-147","title":"Saúde não é só ausência de doença","text":"A Constituição da Organização Mundial da Saúde conceitua saúde abrangendo bem-estar físico, mental e social, e não apenas ausência de doença ou enfermidade.","usage":"Amplie o argumento para condições de vida e saúde mental, sem transformar a definição em prova de causalidade ou promessa de bem-estar permanente.","source":"Constituição da OMS — fonte primária para consulta.","sourceURL":"https://www.who.int/about/governance/constitution","category":"Pensadores e conceitos","axes":["Saúde","Cidadania"],"kind":"Biblioteca ampliada · paráfrase","warning":"Paráfrase editorial da fonte indicada. Distinga tratado, declaração, conceito e legislação nacional; não transforme a referência em estatística ou citação literal."}];
